using System;
using System.Collections.Generic;
using System.Linq;

namespace FrioCalc.Psychrometrics.Processes;

// [4.17] Curso ORIGINAL guiado por el orden del cap. 1 ASHRAE 2025.
// No reproduce textualmente el Handbook ni los ejercicios de una presentación.
public sealed record AshraeStudyUnit(
    string Id,string AshraeSection,string Title,string Definition,
    string Derivation,string Origin,string Interpretation,
    string Limitation,string EquationKey,string Example,string Source)
{
    public string DisplayTitle => AshraeSection+" · "+Title;
}

public sealed record AshraeEquation(
    string Key,string Title,string Left,string Numerator,string Denominator,
    string Units,string Derivation,string Origin,string Limitations);

public sealed record ChartConstructionStep(
    int Number,string Title,string WhatToDo,string WhyThisMatters,
    string NumericalExample,string Basis,string UnitId)
{
    public string DisplayTitle => Number.ToString("00")+". "+Title;
}

public static class AshraeStudyCatalog
{
    public const string PrimarySource="ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx";
    public const string SecondarySource="PsychroLib, funciones de aire húmedo: https://psychrometrics.github.io/psychrolib/api_docs.html";
    public static IReadOnlyList<AshraeStudyUnit> Units { get; }=new[]
    {
        new AshraeStudyUnit("A1", "§1. Composición del aire", "Aire seco, vapor de agua y mezcla", "El aire húmedo es una mezcla de aire seco y vapor de agua. Se adopta la masa de aire seco como base de los balances.", "Ley de Dalton para mezclas ideales: la presión total es la suma de presiones parciales de aire seco y vapor. La humedad varía sin cambiar la masa de aire seco.", "La composición del aire seco se obtiene de análisis atmosféricos; las masas molares proceden de mediciones. La relación de gases ideales es un modelo teórico.", "Antes de calcular, distinga m_da, m_v, P, p_da y p_v. Un estado humidificado contiene más vapor por kg de aire seco.", "La presencia de aerosoles, agua líquida, hielo o contaminantes requiere un modelo con fases adicionales.", "W", "Ejemplo: 25°C y 50% HR a 101,325 kPa producen W ≈ 9,9 g/kgda.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A2", "§2. Atmósfera estándar", "Presión absoluta, altitud y condiciones de referencia", "La presión barométrica depende de altitud y tiempo meteorológico; la atmósfera estándar es una referencia, no una medición local.", "La presión estándar se calcula integrando la ecuación hidrostática con perfiles de temperatura y aproximación de gas ideal.", "El perfil atmosférico se basa en un modelo normalizado con constantes y datos meteorológicos.", "Cambie la presión en el panel de trabajo: Ws, Tbh, v y las curvas cambian aun para la misma Tbs.", "No sustituya presión absoluta por manométrica; altitud sola no predice el tiempo atmosférico real.", "V", "Ejemplo: 3000 m de atmósfera estándar ≈ 70,108 kPa, no 101,325 kPa.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A3", "§3. Propiedades termodinámicas", "Energía, entalpía, volumen y referencias", "El estado se describe con T, P y composición; h y v sirven para balances de energía y caudal de aire seco.", "La entalpía de mezcla ideal suma contribuciones de cada componente. El volumen procede de PV=mRT aplicado a ambos gases.", "Los coeficientes de calor específico son propiedades medidas y ajustadas. El modelo ideal es una aproximación; ASHRAE ofrece modelos de aire real.", "Las magnitudes h y v están referidas a kg de aire seco. Una diferencia h2−h1 se convierte en kW solo con ṁ_da.", "La entalpía tiene referencia convencional (aprox. 0°C). No interpretar su valor como energía absoluta de un sistema.", "h", "Ejemplo: con 25°C/50% HR, h del aire húmedo se calcula por suma de aire seco y vapor.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A4", "§4. Presión de saturación", "Equilibrio agua-vapor y presión de saturación", "p_ws(T) es la presión de equilibrio del vapor sobre agua o hielo a la temperatura dada. Su valor crece rápidamente con T.", "Se deduce conceptualmente de igualdad de potencial químico entre fases; para calcular se emplean correlaciones y formulaciones termodinámicas validadas.", "Las constantes de las formulaciones ASHRAE/Hyland-Wexler e IAPWS proceden de investigación y ajuste de datos experimentales; no son una simple identidad algebraica.", "Para cada T del eje horizontal, calcule p_ws(T), luego Ws(T,P) y marque el límite saturado.", "La transición agua/hielo y la corrección del factor de mejora modifican los resultados del modelo real.", "Ws", "Ejemplo: a 25°C la presión de saturación es cercana a 3,17 kPa; cambiar P modifica Ws.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A5", "§5. Parámetros de humedad", "W, humedad relativa, humedad específica y humedad volumétrica", "Razón de humedad W=m_v/m_da; humedad específica γ=m_v/(m_da+m_v); humedad relativa φ es relación de presiones de vapor y saturación.", "W se obtiene de Dalton y gases ideales; γ se deduce por conservación de masas; HR se define frente a la condición saturada.", "La humedad se mide con higrómetros/psicrómetros/sensores de rocío; las relaciones provienen de definiciones y modelos físicos.", "FrioCalc usa la etiqueta «humedad absoluta» para W por petición del proyecto; estrictamente ASHRAE llama humedad absoluta d_v=m_v/V.", "No confundir g/kgda, kg/kgda, %, kg vapor/m³; no se pueden intercambiar unidades ni magnitudes.", "W", "Ejemplo: 10 g/kgda corresponde a W=0,010 kg/kgda, no a 10% HR.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A6", "§6. Relaciones de gas ideal", "Deducción de W, h y v", "La ley de gases ideales y la base de aire seco permiten derivar ecuaciones explícitas de W y v; h requiere cp y una referencia.", "Usar P V=nRT para cada gas, Dalton y cociente de masas molares: W=(Mv/Mda)(pv/pda).", "La estructura de ecuación es teórica; Mv/Mda, cp y h_fg0 son magnitudes medidas o evaluadas experimentalmente.", "Construya primero W y luego h y v. Un valor de presión erróneo contamina todos los resultados.", "La precisión del modelo ideal disminuye cuando las hipótesis de idealidad fallan; compare con ASHRAE RP-1485 cuando corresponda.", "W", "Ejemplo: derivar 0,621945 de 18,015257/28,966.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A7", "§7. Bulbo húmedo y rocío", "Temperaturas características de humedad", "Tdp es la temperatura de saturación a la presión parcial de vapor actual; Tbh termodinámico describe saturación adiabática con agua.", "Tdp es raíz de p_ws(Tdp)=pv. Tbh proviene de balance de masa de agua y entalpía durante saturación adiabática.", "Las medidas con termómetro de bulbo húmedo dependen de instrumentación, ventilación y condiciones; el bulbo húmedo termodinámico se define mediante balance.", "En la carta, para rocío vaya horizontal a saturación. Para Tbh use isolíneas calculadas por su balance.", "Las líneas de Tbh no son exactamente isoentálpicas; a W=0 el rocío no está definido.", "Tdp", "Ejemplo: compare Tbs, Tbh y Tdp para el estado actual.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A8", "§8. Propiedades de transporte", "Viscosidad, conductividad y difusión", "El flujo de calor y masa depende de conductividad, viscosidad, difusión y propiedades de mezcla, distintas de las coordenadas del estado psicrométrico.", "Las ecuaciones de transporte y las correlaciones de propiedades permiten estimar flujo a través de equipos.", "Los coeficientes de transporte dependen de teorías moleculares y ajustes experimentales; ASHRAE cita Herrmann y colaboradores.", "Estas propiedades se usan posteriormente para calcular transferencia de calor y caída de presión, pero no añaden una escala simple a la carta.", "La carta de estados no sustituye el dimensionamiento térmico de serpentines, intercambiadores o ventiladores.", "h", "Ejemplo: calcular h2−h1 no determina por sí mismo el área de transferencia.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A9", "§9. Cartas psicrométricas", "Convención de ejes y lectura de familias", "La carta traduce las ecuaciones a curvas: temperatura seca, razón de humedad, HR, entalpía, bulbo húmedo y volumen específico.", "Una elección de coordenadas transforma las familias de propiedades. Las cartas ASHRAE emplean coordenadas oblicuas de h y W; FrioCalc visualiza Tbs y W en un plano cartesiano.", "La forma de la carta se deriva de ecuaciones de propiedades y convenciones gráficas; los datos termodinámicos de las cartas ASHRAE emplean modelos de aire real.", "Seleccione dos propiedades independientes; ubique su intersección y compruebe que W≤Ws antes de leer el resto.", "Las curvas de FrioCalc no deben presentarse como reproducción exacta de la geometría y datos reales de la carta oficial ASHRAE.", "Ws", "Ejemplo: una curva de HR=50% se calcula como W(T,0,5,P) para todas las T válidas.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A10", "§9. Construcción detallada", "Construir una carta psicrométrica desde cero", "Este itinerario presenta las decisiones y cálculos que llevan de la presión y las propiedades de gases a cada familia gráfica.", "La derivación no parte de dibujar curvas a mano sino de una tabla de estados obtenida con ecuaciones y un modelo termodinámico declarado.", "Los términos de gas ideal proceden de teoría; p_ws, cp y propiedades reales requieren ecuaciones calibradas o mediciones.", "Recorra los doce pasos de construcción. Cada paso tiene propósito, ecuación, ejemplo numérico, verificación y fuente.", "Este trazado Tbs–W es didáctico; para replicar la carta oblicua ASHRAE se requiere la transformación de coordenadas h–W y la biblioteca de propiedades RP-1485.", "W", "Ejemplo: elija P=101,325 kPa y construya familias entre Tbs=−10 y 55°C hasta W=60 g/kgda.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A11", "§9. Lectura de propiedades", "Resolver un estado con dos propiedades independientes", "Con presión absoluta y dos propiedades compatibles independientes puede calcularse un estado. Una tercera sirve para verificar consistencia.", "Las ecuaciones son relaciones de estado; los inversores se resuelven algebraicamente o con búsqueda de raíces.", "Las entradas se miden con instrumentos o se obtienen como condiciones de diseño; los algoritmos Directo/Numérico son internos de FrioCalc.", "Tbs+HR: hallar pws, pv, W y después h, v, Tdp, Tbh; marcar en el dominio físico.", "Dos datos redundantes no determinan necesariamente un punto único; un estado sobresaturado requiere otro modelo.", "RH", "Ejemplo: 25°C, 50% HR, P=101,325 kPa; calcular W y localizar sobre la carta.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A12", "§10. Procesos de calor sensible", "Calefacción y enfriamiento sensible", "Sin aporte ni retirada de humedad, la razón W no cambia aunque varíe Tbs y la humedad relativa.", "Balance estacionario de energía con flujo de aire seco; Δh por kgda multiplicado por ṁda.", "La ecuación de balance es termodinámica; el rendimiento y las curvas del equipo se miden.", "En carta Tbs–W la transformación se muestra horizontal. Enfriar hasta rocío marca el límite antes de condensar.", "Si hay condensación, humedad añadida o flujo de condensado, el proceso deja de ser únicamente sensible.", "h", "Ejemplo: aire 35→25°C con W=10 g/kgda y 5 m³/s, convertir V̇/v a ṁda.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A13", "§10. Procesos de humidificación", "Inyección de vapor y lavado evaporativo", "Añadir agua modifica W; el vapor transporta entalpía adicional y la evaporación puede enfriar el aire.", "Conservación de masa seca, agua y energía: W2=W1+ΔW y h2=h1+ΔW·h_agua (sin pérdidas).", "La estructura del balance es teórica; h del agua/vapor y efectividad del equipo proceden de datos físicos o catálogo.", "Elegir humidificador, introducir la efectividad o estado del vapor y verificar que la salida no exceda saturación.", "Una efectividad de saturación ideal no equivale a eficiencia comercial; el término de clase no define universalmente un método ASHRAE.", "W", "Ejemplo: con aire a 30°C y 10% HR, cambiar efectividad del lavado.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A14", "§10. Procesos de deshumidificación", "Enfriamiento, condensación y desecantes", "Para eliminar vapor mediante enfriamiento se llega primero al rocío y después se condensa; un desecante retira agua por sorción.", "El balance de agua establece ṁcond=ṁda(W1−W2); el de energía incluye entalpía de condensado.", "El balance es termodinámico; la capacidad del desecante depende de isotermas, regeneración y ensayos de fabricante.", "Dibujar estado 1, rocío, salida saturada; comparar W1 y W2; sumar estados intermedios.", "No asignar una temperatura a un desecante sin sorción ni datos del fabricante.", "W", "Ejemplo: 32°C, rocío 28°C y salida saturada 21°C.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A15", "§10. Mezcla adiabática", "Dos corrientes: balances másicos de aire seco", "Una mezcla sin pérdidas ni condensación conserva flujo de aire seco, vapor y entalpía; caudales volumétricos requieren convertir usando v propio.", "Balances: ṁ3=ṁ1+ṁ2, W3=(ṁ1W1+ṁ2W2)/ṁ3, h3=(ṁ1h1+ṁ2h2)/ṁ3.", "Conservación de masa y energía es teórica; estados, flujos y rendimientos pueden medirse.", "Localice entradas en la carta, derive salida y compruebe W3 y h3 en los límites esperados.", "No use media simple de HR ni de caudales en m³/h; pueden existir mezclas con condensación.", "MixW", "Ejemplo: retorno 3000 m³/h a 24°C/55% y exterior 500 m³/h a 32°C/70%.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A16", "§10. Serpentines y bypass", "ADP y factor de bypass (BF)", "El modelo ideal de serpentín supone mezcla del aire no contactado con aire próximo a saturación a ADP.", "La salida se halla por mezclas lineales idealizadas en W y h: BF requiere ADP además del estado de entrada.", "BF es un parámetro de rendimiento de serpentín a determinar mediante datos experimentales o del fabricante.", "Dibuje entrada→ADP y ubique la salida por la fracción de bypass; verificar condensado y humedad.", "BF por sí solo no identifica estado de impulsión ni desempeño real; curva de serpentín necesaria.", "BF", "Ejemplo: BF=0,20 y ADP especificado, no solo BF.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A17", "§10. Factores de calor sensible", "SHR, RSHF, GSHF y fronteras de balance", "El factor sensible/total vincula ganancias térmicas y latentes; su definición depende de la frontera del recinto o del sistema.", "SHR=Qs/Qt con denominador distinto de cero y convención coherente; exige balances medidos o calculados.", "Es un cociente de balances, no una propiedad tabulada del estado del aire.", "Usar el estado interior y un caudal para determinar una posible salida; verifique cargas y equipo.", "No puede crearse un punto único de impulsión a partir solo de FCS o BF.", "SHR", "Ejemplo: RSH=150 kW, RLH=50 kW implica SHR_local=150/200=0,75.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
        new AshraeStudyUnit("A18", "§10. Sistema de climatización", "UTA, ventilador, serpentín, agua y estados sucesivos", "Una UTA combina exterior/retorno, mezcla, serpentín, ventilador y distribución; cada etapa debe tratarse por separado.", "Balances de masa y energía en cada volumen de control; la suma de cargas depende del orden de los componentes.", "Las leyes de conservación son teóricas; eficiencia, curvas de equipo, ventilador y pérdidas requieren medición/catálogo.", "Marque retorno R, exterior E, mezcla M, serpentín C e impulsión S. Verifique presión, W, h y cargas en cada tramo.", "Las condiciones del aire no determinan automáticamente superficie del serpentín, consumo de agua o capacidad comercial.", "MixW", "Ejemplo: auditorio con 150 kW sensible, 50 kW latente y ventilador que agrega 1,5°C.", "ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx"),
    };
